package com.multistreamcammc.client; import com.multistreamcammc.MultiStreamCamMCMod;import net.fabricmc.api.ClientModInitializer;import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;import net.fabricmc.fabric.api.client.keybinding.v1.KeyBindingHelper;import net.fabricmc.fabric.api.client.networking.v1.ClientPlayNetworking;import net.fabricmc.fabric.api.networking.v1.PacketByteBufs;import net.minecraft.client.MinecraftClient;import net.minecraft.client.option.KeyBinding;import net.minecraft.client.util.InputUtil;import org.lwjgl.glfw.GLFW;import java.util.*; public class MultiStreamCamMCClient implements ClientModInitializer{private static KeyBinding key;public void onInitializeClient(){key=KeyBindingHelper.registerKeyBinding(new KeyBinding("key.multistreamcammc.menu",InputUtil.Type.KEYSYM,GLFW.GLFW_KEY_K,"category.multistreamcammc"));ClientPlayNetworking.registerGlobalReceiver(MultiStreamCamMCMod.CAMERA_SYNC_PACKET,(client,h,buf,rs)->{List<ClientCameraEntry> e=new ArrayList<>();int n=buf.readVarInt();for(int i=0;i<n;i++)e.add(new ClientCameraEntry(buf.readString(),buf.readString(),buf.readBlockPos(),buf.readFloat(),buf.readFloat()));client.execute(()->client.setScreen(new CameraQuickMenuScreen(e)));});ClientTickEvents.END_CLIENT_TICK.register(c->{while(key.wasPressed())ClientPlayNetworking.send(MultiStreamCamMCMod.CAMERA_REQUEST_PACKET,PacketByteBufs.empty());});}}
